CREATE TABLE whatsapp_events (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, dedupe_key VARCHAR(255) NOT NULL, kind VARCHAR(16) NOT NULL, phone_number_id VARCHAR(64) NULL, user_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL, payload JSON NOT NULL, status VARCHAR(16) NOT NULL DEFAULT 'pending', attempts INT NOT NULL DEFAULT 0, error TEXT NULL, locked_at DATETIME(6) NULL, received_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), processed_at DATETIME(6) NULL, PRIMARY KEY (id), UNIQUE KEY whatsapp_events_dedupe_uq (dedupe_key), KEY whatsapp_events_due_idx (status,received_at), CONSTRAINT whatsapp_events_kind_ck CHECK (kind IN ('message','status','other')), CONSTRAINT whatsapp_events_status_ck CHECK (status IN ('pending','processing','done','ignored','failed')), CONSTRAINT whatsapp_events_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci